def modinv(a, mod=MOD):
    return pow(a, mod - 2, mod)

def factorize(n):
    factors = {}
    while n % 2 == 0:
        factors[2] = factors.get(2, 0) + 1
        n //= 2
    i = 3
    while i * i <= n:
        while n % i == 0:
            factors[i] = factors.get(i, 0) + 1
            n //= i
        i += 2
    if n > 1:
        factors[n] = 1
    return factors

def main():
    n, k = map(int, sys.stdin.readline().split())
    factors = factorize(n)
    result = 1
    for p, e in factors.items():
        max_e = e
        prev = [0] * (max_e + 1)
        prev[max_e] = 1
        for _ in range(k):
            curr = [0] * (max_e + 1)
            prefix = [0] * (max_e + 1)
            prefix[0] = prev[0]
            for i in range(1, max_e + 1):
                prefix[i] = (prefix[i-1] + prev[i]) % MOD
            for j in range(max_e + 1):
                curr[j] = prefix[j] % MOD
            prev = curr
        total = 0
        for j in range(max_e + 1):
            total = (total + prev[j] * pow(p, j, MOD)) % MOD
        denom = pow(max_e + 1, k, MOD)
        inv_denom = modinv(denom)
        term = total * inv_denom % MOD
        result = result * term % MOD
    print(result)

